def countByDigitSum(low, high, minSum, maxSum):
    MOD = 10 ** 9 + 7
    L = max(len(low), len(high))
    W = maxSum + 1
    exact = [[0] * W for _ in range(L + 1)]
    exact[0][0] = 1
    for l in range(1, L + 1):
        prev = exact[l - 1]
        pre = [0] * (W + 1)
        for t in range(W):
            pre[t + 1] = pre[t] + prev[t]
        cur = exact[l]
        for t in range(W):
            cur[t] = (pre[t + 1] - pre[max(0, t - 9)]) % MOD
    ways = []
    for l in range(L + 1):
        run = 0
        row = []
        for t in range(W):
            run = (run + exact[l][t]) % MOD
            row.append(run)
        ways.append(row)

    def upto(s, T):
        if T < 0:
            return 0
        n = len(s)
        res = 0
        pre = 0
        for i, ch in enumerate(s):
            d = int(ch)
            rem = n - i - 1
            for dd in range(d):
                t = T - pre - dd
                if t < 0:
                    break
                res += ways[rem][t]
            pre += d
            if pre > T:
                return res % MOD
        return (res + 1) % MOD

    def good(s):
        return (upto(s, maxSum) - upto(s, minSum - 1)) % MOD

    ans = good(high) - good(low)
    if minSum <= sum(int(c) for c in low) <= maxSum:
        ans += 1
    return ans % MOD
